INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'd3779c7b-28e1-4775-a965-c47ecbe7943a',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门奥普拓自控科技有限公司' LIMIT 1),
  '2026年度区域发展项目申报指南',
  0,
  '强烈推荐申报（A级）。企业完全满足所有申报条件，特别是研发投入强度（38.41%）、知识产权储备（40件）、科技人员占比（66.67%）等核心指标均远超政策要求。建议立即启动申报准备工作，重点关注：1）提前与厦门市科技局沟通省级科技经费配套事宜；2）确认项目负责人符合同期主持项目数不超过1项的要求；3）准备高新技术企业证书、研发准备金制度文件等支撑材料。由于企业财务数据显示利润为负，建议在申报材料中突出研发投入的战略性意义和未来产业化前景。'
);
