INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '398cde7a-fd27-4a48-ae7e-f605c5ea0f84',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门奥普拓自控科技有限公司' LIMIT 1),
  '关于2025年企业研发费用补助相关事项的通知',
  0,
  '强烈推荐申报。该企业注册地在厦门、信用良好、2024年度研发费用770.05万元远超200万元门槛、已成功申报加计扣除，前置条件和门槛条件均完全满足。唯一需要补充核实的是2023年度研发费用数据以确认增长率。建议：1）立即调取2023年度研发费用账目，确认同比是否增长；2）若2023年度无研发费用，则增长条件自动满足，可直接申报；3）若2023年度有研发费用，需确保770.05万元高于该数值；4）准备完整的研发费用辅助账、决算报告等证明材料，确保数据可追溯、可核实。'
);
