INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'a84e1dd4-3287-4e48-bc12-aa0741abc73c',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门奥普拓自控科技有限公司' LIMIT 1),
  '政府间国际科技创新合作重点专项2025年度第二批人员交流项目申报指南',
  0,
  '强烈推荐申报。企业完全满足所有前置条件，政策无财务门槛限制，企业在高新技术企业资质、研发投入、科技人员配置和知识产权方面均表现优秀。建议重点准备以下材料：1）梳理企业已有的国际合作基础（如与境外机构的合作协议、交流记录等）；2）制定明确的人员交流计划，包括交流目的、预期成果、合作外方单位信息；3）突出企业在软件和信息技术服务领域的专业技术优势和国际合作潜力。虽有亏损，但政策重点考察国际合作基础而非财务指标，申报风险较低。'
);
