INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'a42f531e-3138-4c3c-b134-0e366bf25f29',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门奥普拓自控科技有限公司' LIMIT 1),
  '福建省科学技术厅关于组织申报2026年度第一批省科技计划和奖补项目的通知',
  0,
  '企业整体符合政策申报条件，建议申报。研发投入强度（38.41%）和知识产权积累（40件）是重要优势，高新技术企业资质和规模以上企业身份也符合优先支持条件。建议立即采取以下行动：1. 确认是否已取得2025年度科技型中小企业入库登记编号；2. 确认是否为省级新型研发机构；3. 提前建立研发准备金制度；4. 关注财务状况改善，特别是利润转正。综合评分87.77分，评级B级，建议申报。'
);
