INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'a82722fb-c8dc-4c11-8768-49cd5265eaab',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门奥普拓自控科技有限公司' LIMIT 1),
  '2025年 厦门市新型研发机构管理办法',
  1,
  '该企业研发投入、研发人员、投入强度等核心指标均远超政策要求，具备良好的申报基础。但存在两个关键障碍：1）尚未认定为市级新型研发机构（前置条件不满足）；2）研发设备原值未明确。建议分两步走：第一步，先申请认定市级新型研发机构；第二步，同步补充完善研发设备原值审计报告、公司章程治理结构、科研场所独立性证明等材料。如能解决上述问题，可优先申报重点级新型研发机构（每年最高300万元补助），条件成熟后再申报重大级（每年最高1000万元补助）。'
);
