INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '01d9a6fb-88b0-41f9-a996-367752c25bfd',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门奥普拓自控科技有限公司' LIMIT 1),
  '2025年福建省院省科技合作计划项目管理实施细则',
  1,
  '该政策要求福建省企业与中国科学院院属研究所联合申报，属于院省科技合作专项。企业虽具备独立法人资格、注册地符合要求、知识产权储备丰富、配套资金能力充足，但**最关键的障碍是缺乏与中国科学院院属研究所的合作关系**。建议：1.暂不推荐申报该政策；2.如企业有与中科院相关研究所的合作意向或正在洽谈中，可先进行前期对接；3.可关注福建省其他科技计划项目，优先申报不要求院省合作的政策。'
);
