INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '0199b1b0-5d64-4aba-8d99-f94811954a39',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门奥普拓自控科技有限公司' LIMIT 1),
  '海沧区2025年国家级高新技术企业认定奖励',
  1,
  '该企业除注册地外，各项指标均远超政策要求，但因注册地在湖里区而非海沧区，属于一票否决项，无法申报海沧区2025年国家级高新技术企业认定奖励。建议：1）关注湖里区或其他区的同类高企认定奖励政策；2）如企业有迁移至海沧区的计划，可考虑迁移后再申报；3）确认高企首次认定时间，确保符合政策要求。'
);
