INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '0659d69f-006c-44b2-9ce9-852ec7d0e6e8',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门奥普拓自控科技有限公司' LIMIT 1),
  '厦门市留学人员创业扶持工作指引',
  1,
  '该企业门槛条件和核心条件表现优秀（研发投入、研发人员、高企资质均达标），但存在两个致命前置条件缺陷：①企业成立已超过12年，远超政策要求的5年限制；②无法确认留学人员创办身份。建议：1. 确认政策中\'5年以下\'是否为项目阶段要求而非企业成立年限要求；2. 核实企业创始人/实际控制人是否为留学人员；3. 如上述问题无法解决，建议放弃该政策申报，转向其他适合成熟期科技企业的扶持政策。'
);
