INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'a7796722-6c8e-4d21-82e8-0b65e3fe6189',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门奥普拓自控科技有限公司' LIMIT 1),
  '2026年度科技型中小企业技术创新资金项目申报指南',
  1,
  '该企业整体资质优秀，研发投入强度、科技人员占比、知识产权数量等核心指标均表现突出，核心技术领域也完全契合政策支持方向。但由于注册地在厦门市，而政策明确要求福建省（不包括厦门市），属于一票否决项，因此**不建议申报该政策**。建议：1）关注福建省内（不包括厦门）其他科技政策；2）如政策调整或企业有异地布局计划，可考虑在福州、泉州等地设立子公司申报；3）该企业资质优秀，可优先考虑申报厦门市本地科技政策。'
);
