INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '7bb20cb2-e340-4d22-9a62-c16cfe11b310',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门奥普拓自控科技有限公司' LIMIT 1),
  '2026年度星火项目申报指南',
  0,
  '不建议申报该政策。企业所属行业为软件和信息技术服务业，与政策要求的农业科技领域存在根本性差异，属于核心条件完全不匹配。虽然企业在研发投入强度、知识产权储备等方面表现优秀，但政策明确要求支持农业领域的种业、种植业、养殖业、农产品加工、农业机械装备、数智农业等技术方向，企业的主营业务和技术方向与此完全不符。建议企业寻找与软件和信息技术服务业相关的政策支持，如科技计划中的软件信息类项目。'
);
