INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'cf2e5cd6-928b-4138-af9a-9fc2d20281f5',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门金龙汽车座椅有限公司' LIMIT 1),
  '2025年 厦门市科学技术奖励办法',
  0,
  '企业整体资质良好，前置条件和门槛条件均满足，但核心条件存在明显短板。建议优先采取以下措施：1）立即核查是否已办理科技成果登记并取得登记号，这是申报的前提条件；2）梳理企业近年来的技术成果和获奖情况，如有符合条件的科技成果应积极申报；3）整理参与制定的标准情况；4）在申报材料中重点突出汽车座椅领域的关键技术创新成果和转化效益，以弥补基础研究方面的不足。综合评估后，建议申报。'
);
