INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'b104f67e-ae3a-49ea-b40c-0f39d36fb443',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门金龙汽车座椅有限公司' LIMIT 1),
  '2025年福建省院省科技合作计划项目管理实施细则',
  0,
  '该企业整体资质较好，前置条件和核心条件大部分满足，但该政策要求必须与中国科学院院属研究所联合申报，这是申报的核心前提条件。建议企业：1.优先寻找与汽车座椅、新能源汽车、轻量化等相关的中国科学院院属研究所建立合作关系；2.依托企业现有的研发机构和高新企业资质，与中科院研究所洽谈联合申报事宜；3.利用企业现有的36件知识产权和较强的研发团队，作为与技术对接的亮点；4.提前准备技术合同和合作经费安排，确保满足30%-50%合作经费要求。完成联合申报单位确定后，可达到A级申报标准。'
);
