INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '126824a4-04af-4235-b2e7-ce993b061870',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门金龙汽车座椅有限公司' LIMIT 1),
  '2026年度引导性项目申报指南',
  0,
  '该企业在研发投入、知识产权、科技人员、技术领域等方面均表现优秀，完全契合工业科技领域的支持方向，且注册地为厦门符合地域要求。但政策明确要求申报主体为省直企事业单位，而该企业为民营企业，存在主体性质不匹配的风险。建议：1）首先与省科技厅或厦门市科技局确认民营企业是否有申报资格；2）如确认可申报，应重点突出企业在先进制造领域的技术创新性和对产业发展的支撑作用；3）可考虑与省直科研院所联合申报，弥补主体资格问题；4）项目申请金额建议控制在10-20万元区间，与政策要求匹配。综合评定为C级，可尝试申报但需解决主体资格问题。'
);
