INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '13898628-2bd8-4f5d-a347-4b6b64dd4020',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门金龙汽车座椅有限公司' LIMIT 1),
  '2021年 厦门市科学仪器设备资源共享管理办法',
  0,
  '该政策主要针对科学仪器设备资源共享平台的管理，企业作为汽车座椅制造企业，主营业务与科学仪器设备共享服务关联度较低。建议企业：1）首先核实是否拥有符合条件的科学仪器设备；2）评估建立科学仪器设备开放共享管理制度的可行性；3）考虑作为\'使用方\'而非\'提供方\'申报使用补助（实际发生费用的30%，每年最高50万元）；4）如无符合条件的仪器设备，暂不推荐申报该政策。'
);
