INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '4ddcfe1f-70d2-480b-952d-a2f389ec56c4',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门金龙汽车座椅有限公司' LIMIT 1),
  '《厦门市新型研发机构管理办法》的政策解读',
  0,
  '该企业暂不推荐申报《厦门市新型研发机构管理办法》。虽然企业在注册地、研发人员数量、研发投入金额等方面表现良好，但存在两个关键障碍：一是研发投入强度仅4.87%，远低于政策要求的30%，达标率仅16.23%，这是硬性门槛差距；二是企业所属的汽车制造业不在政策支持的十大核心技术领域范围内，核心条件不匹配。建议企业先提升研发投入强度至30%以上，同时论证汽车座椅技术与政策支持领域的关联性，或考虑申报其他更匹配的政策。'
);
