INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'f6a443d6-6339-4db7-85dd-acf15975ddb1',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门金龙汽车座椅有限公司' LIMIT 1),
  '2026年厦门市联合实验室申报',
  1,
  '暂不推荐申报该政策。主要原因：1）企业所属行业（汽车制造业）不在政策明确支持的九大战略性新兴产业和未来产业领域范围内，这是根本性障碍；2）缺少必要的共建单位（高校、科研院所等）；3）龙头企业资格未确认。建议：1）核实企业是否为厦门市汽车产业的龙头企业；2）寻找符合政策方向的战略性新兴产业共建单位；3）关注厦门市是否有针对汽车产业的专项政策；4）如条件允许，可考虑调整主营业务方向或与战略性新兴产业企业合作申报。'
);
