INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '89220b8b-683d-4438-b056-e20abdbf51ae',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门金龙汽车座椅有限公司' LIMIT 1),
  '2026年度发展中国家技术培训班项目申报指南',
  0,
  '**暂不推荐申报该政策。** 虽然企业具备独立法人资格和高新技术企业资质，但主营业务为汽车座椅制造，与政策要求的\'技术培训班项目实施\'完全不匹配，且企业无任何国际培训项目经验、无外籍学员资源渠道。建议企业关注与自身业务相关的科技政策，如汽车制造业技术改造、智能制造、科技成果转化等相关政策。如确需申报此类援外培训项目，建议先积累国际培训经验，建立外籍学员渠道，再择机申报。'
);
