INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'fd3e00b1-6038-46fa-92bc-73cdccaab2df',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门金龙汽车座椅有限公司' LIMIT 1),
  '2026年度科技特派员后补助项目申报指南',
  1,
  '**暂不推荐申报该政策。** 该政策明确要求申报项目须围绕农业特色产业或乡村振兴相关产业链，而企业属于汽车制造业，主营业务为汽车座椅制造，与政策支持方向存在根本性差异。此外，无法确认企业是否为科技特派员服务对接单位，以及是否有符合条件的省级个人科技特派员作为项目负责人。建议企业关注与汽车制造、新能源、智能网联等相关的科技政策，或探索向农业机械、乡村振兴配套等领域转型后再考虑申报此类政策。'
);
