INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'b38a3a80-46a0-4c21-b857-52a780759423',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门柔性电子研究院有限公司' LIMIT 1),
  '技术合同认定登记办事指南',
  0,
  '强烈推荐申报。企业完全满足技术合同认定登记的前置条件（注册地、法人资格、申报主体均符合），核心条件（技术领域匹配度）也基本满足。作为高新技术企业、研发机构，且拥有丰富的知识产权储备和强大的研发团队（科技人员占比91.67%），企业具备从事技术开发、技术转让、技术许可、技术咨询、技术服务的能力和资质。建议：1）梳理企业已有的技术合同，确认是否符合认定条件；2）如有无技术合同，尽快规范签订；3）准备大额合同所需的技术方案和知识产权证书；4）关注奖励金政策（年实际技术交易金额3000万元及以下按1%奖励，最高100万元），积极争取奖励。'
);
