INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'c8f065df-6374-4e64-b460-6f0060c2b34d',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门柔性电子研究院有限公司' LIMIT 1),
  '厦门市新型研发机构管理办法',
  0,
  '建议申报**重点新型研发机构**。企业整体符合申报条件，前置条件全部满足，研发人员数量和占比远超要求，核心技术领域与政策支持方向高度契合。主要风险点在于年度研发投入（174.35万元）略低于重点机构200万元要求25.65万元，以及研发投入强度（29.74%）略低于30%要求。建议：1）核实研发投入统计口径，确认是否可调整至200万元以上；2）补充研发设备原值证明材料（建议达到200万元以上）；3）补充技术开发等服务收入证明材料；4）完善研发管理制度和章程；5）确认是否已认定为新型研发机构。完成上述补充后，申报成功率将显著提升。'
);
