INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'ebc415c0-5a36-4c70-b29b-a8e4e05798ce',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门柔性电子研究院有限公司' LIMIT 1),
  '关于组织申报2024年公共技术服务平台项目的通知',
  0,
  '企业整体匹配度较好，建议优先申报。建议采取以下措施：1）补充研究院性质的说明材料，论证其作为公共技术服务平台的功能定位；2）提供场地使用证明，确认场所面积满足500平方米要求；3）编制自筹资金能力说明，结合企业资产和营收情况论证2:1自筹比例的可行性；4）强化平台公益性和开放性特征的描述，突出其技术服务能力和社会效益。政策支持金额最高500万元（其他平台）或2000万元（特别重大平台），建议根据平台建设规模选择合适的申报类别。'
);
