INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'ca4e7b66-1895-41b2-9fb3-0aaf9d796b80',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门柔性电子研究院有限公司' LIMIT 1),
  '关于组织申报2025年度市级新型研发机构的通知',
  0,
  '建议申报重点层级新型研发机构。企业在科技人员占比（91.67%）、研发投入强度（29.74%）、技术领域匹配度等方面表现优秀，完全满足前置条件和核心条件。主要风险点是年度研发投入（174.35万元）未达到重点层级200万元要求，差25.65万元。建议：1）在申报前将研发投入补足至200万元以上；2）补充研发设备原值证明材料（需≥200万元）；3）准备完善的财务和设备清单材料以应对评审。重大层级因研发投入和设备原值差距过大，暂不推荐申报。'
);
