INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '38e3ce45-8a65-426b-89d6-7f745fa160ed',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门柔性电子研究院有限公司' LIMIT 1),
  '2026年度区域发展项目申报指南',
  1,
  '**暂不推荐申报该政策。** 核心问题在于企业不符合"规模以上企业"的前置条件要求（主营业务收入528.9万元<1000万元，职工24人<50人），属于一票否决项。建议企业优先通过以下路径提升资质：1）扩大业务规模，争取营收突破1000万元；2）扩充员工队伍至50人以上；3）确认并建立研发准备金制度。在满足规模以上企业标准后，该企业的研发投入强度（29.74%）、高企资格、知识产权储备等优势将使其成为极具竞争力的申报对象。'
);
