INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'c0848cdb-347e-4634-827f-ef1e9d83663f',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门柔性电子研究院有限公司' LIMIT 1),
  '厦门市留学人员创业扶持工作指引',
  1,
  '该企业虽然门槛条件（职工、研发人员、研发投入）和部分核心条件（高企资格、领域匹配）均完全满足，但存在两项前置条件硬性不满足：1）企业成立已超过5年，超出政策期限限制；2）无法确认是否为留学人员创办企业。根据一票否决原则，该企业暂不符合该政策申报条件。建议：1）等待政策期限调整或关注其他适合已成立5年以上企业的政策；2）如企业确为留学人员创办，需补充提供相关证明材料；3）可考虑申报其他不限制成立年限的科技型企业扶持政策。'
);
