INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '1828f419-d04c-4bd0-be82-86dcdbd46d46',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门柔性电子研究院有限公司' LIMIT 1),
  '2026年度省创新战略研究项目申报指南',
  1,
  '**暂不推荐申报该政策。** 核心障碍在于申报主体资格不符合政策要求——该政策主要面向高等院校、省属事业单位等科研机构，企业仅在设立智库且纳入福建省重点智库名单的情况下可申报。该企业为一般性有限公司，不属于高校/事业单位范畴，且未明确是否设立智库或纳入福建省重点智库名单。建议企业：(1)核实是否已设立智库并纳入福建省重点智库名单；(2)如已纳入，可准备相关证明材料尝试申报；(3)如未纳入，建议关注其他更适合企业性质的政策，如省级科技计划项目（产业化类）、高新技术企业认定奖励等。'
);
