INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'eda4f051-4030-4864-a79c-45741a5ac115',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门柔性电子研究院有限公司' LIMIT 1),
  '2026年度引导性项目申报指南',
  1,
  '**暂不推荐申报该政策**。虽然企业在技术领域、知识产权、研发能力等方面均符合甚至超出政策要求，但申报主体资格不符合是硬性障碍（一票否决项）。该政策明确要求申报主体为"省直具有法人资格并具备科研开发能力和条件的企事业单位"，而该企业为民营企业，不具备申报资格。建议：1）寻找其他更适合民营企业申报的省级或市级科技计划项目；2）关注厦门市地方科技政策，可能有更适合该企业的申报渠道；3）如确需申报省级项目，可考虑与省直企事业单位联合申报。'
);
