INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '36d195e0-0a2f-4b38-8b6f-68f573638197',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门柔性电子研究院有限公司' LIMIT 1),
  '2026年度星火项目申报指南',
  0,
  '**暂不推荐申报该政策。** 虽然企业在注册地、法人资格、信用状况、研发投入强度等方面表现优秀，但存在两个致命问题：一是企业所属行业为科学研究和技术服务业，与政策要求的农业科技领域完全不匹配；二是核心技术领域为柔性电子，与种业、种植业、养殖业、农产品加工、农业机械装备、数智农业均无关联。这两个核心条件的不匹配是申报的最大障碍。建议企业：一是寻找与柔性电子技术相关的科技政策进行申报；二是如确有农业领域业务拓展需求，可考虑与农业科技企业合作申报。'
);
