INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '213c2859-dcc6-4b6f-9d44-2ee23d322180',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门柔性电子研究院有限公司' LIMIT 1),
  '关于组织申报2026年厦门市应用场景类揭榜挂帅项目（生物技术与生物制造领域）的通知',
  1,
  '暂不推荐申报该政策。主要障碍：(1)缺少联合申报的场景供给方，属于一票否决项；(2)核心技术领域严重不匹配，企业为柔性电子研究院，而政策明确要求生物技术与生物制造领域。如企业有意向申报，建议：(1)寻找生物技术与生物制造领域的场景供给方建立联合申报关系；(2)评估企业技术是否可应用于生物制造相关场景；(3)考虑转向其他与柔性电子领域匹配的政策进行申报。'
);
