INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'd6d8ddae-eaf6-46f8-bcb4-9105dab747f0',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门柔性电子研究院有限公司' LIMIT 1),
  '厦门市科学技术局关于组织申报2026年度国家科技重大项目资金配套的通知',
  0,
  '该企业除基本资质和信用条件完全符合外，在研发投入、科技人员配置、知识产权储备等方面表现优秀，但**缺少国家科技重大项目立项及到位资金信息**，这是该政策的核心申报条件。建议企业：（1）核实是否承担了国家重点研发计划、国家科技重大专项等项目；（2）如已承担相关项目，补充提供立项文件及资金到位证明；（3）补充材料后重新评估申报资格。若能提供国家科技重大项目立项及到位资金证明，评级可提升至B级（85分），建议申报。'
);
