INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '994845fd-a55c-40fa-9643-81d1fe9a305d',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门柔性电子研究院有限公司' LIMIT 1),
  '2026年度科技特派员后补助项目申报指南',
  1,
  '**暂不推荐申报该政策。** 该政策为科技特派员后补助项目，核心要求是围绕农业特色产业或乡村振兴相关产业链开展技术开发。厦门柔性电子研究院有限公司属于科学研究和技术服务业，主营柔性电子技术研发，与政策支持的农业农村领域完全不匹配，这是根本性的障碍。此外，企业无法确认是否为科技特派员服务对接单位，以及是否有符合条件的项目负责人。建议该企业寻找与柔性电子、新材料、电子信息等领域相关的科技政策进行申报，如高新技术企业认定相关政策、科技创新项目等。'
);
