INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '4321c14b-f51e-4a66-b953-cb84707506b5',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门柔性电子研究院有限公司' LIMIT 1),
  '2026年度支持设区市农科院所建设专项项目申报指南',
  1,
  '该企业不符合本政策的申报条件，存在4项一票否决前置条件：1.企业性质为企业而非公益类农业科研院所；2.注册地在厦门而政策要求不含厦门；3.经营范围为柔性电子而非农业领域；4.核心技术领域不匹配。建议企业寻找与柔性电子、智能制造、电子信息等相关的科技政策进行申报，或考虑在福建省其他设区市设立农业相关的子公司（需满足公益类农业科研院所条件）后再申报此类政策。'
);
