INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '820fde4c-5b9b-4ed7-850f-bed0de8f85d3',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱芯环保科技（厦门）股份有限公司' LIMIT 1),
  '技术合同认定登记',
  0,
  '爱芯环保科技（厦门）股份有限公司完全满足技术合同认定登记的全部前置条件和核心条件，强烈推荐申报。该企业作为注册地在厦门的高新技术企业，具备技术开发和服务的业务属性，已享受研发费用加计扣除且拥有丰富的知识产权积累，符合技术合同认定登记的基本要求。建议企业：1）梳理现有技术合同，确保符合技术开发、转让、许可、咨询或服务任一类型；2）规范技术合同文本，确保合同要素完整、条款清晰；3）及时进行技术合同认定登记；4）根据实际技术交易金额（3000万元及以下按1%、超过3000万元部分按0.5%）测算可获得的奖励金额，最高不超过100万元。'
);
