INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'ffbae609-f44e-4138-97c7-31b098964ebe',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱芯环保科技（厦门）股份有限公司' LIMIT 1),
  '关于开展2026年度厦门市产学研合作项目补助兑现工作的通知',
  0,
  '该企业整体符合产学研合作项目补助政策的基本申报条件，前置条件和门槛条件均完全满足。建议重点关注以下事项：1）核实具体产学研合作项目是否已完成技术合同认定登记；2）确认合作合同类型为技术开发或技术转让；3）核实与高校科研院所的控股关系；4）整理项目成效材料，证明技术已在企业实际应用；5）确认项目负责人为高校科研院所在职科研人员；6）确保项目在2025年度内完成并通过验收。由于企业处于亏损状态，需重点准备项目验收材料，证明项目已形成明确成效。建议选择1-2个符合条件的项目进行申报，单个项目最高可获100万元补助。'
);
