INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'a97ea85c-b9eb-46d1-bd1d-d768130e3b7a',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱芯环保科技（厦门）股份有限公司' LIMIT 1),
  '关于深化拓展科技创新引领工程 推动科技创新和产业创新深度融合的若干措施',
  0,
  '企业整体符合政策申报条件，建议申报。核心优势在于注册地、研发投入和营收规模均达标，且已具备高企资格。主要风险点是研发投入增长率无法确认（需补充上年数据）以及领域匹配度。建议：1.补充2024年研发费用数据，确认是否实现增长；2.准备材料论证环保专用设备与政策支持领域的关联性；3.确认科技型中小企业入库状态；4.可申报研发投入补助（每满200万给予10万补助，最高500万），预计可获得约20万元基础补助。'
);
