INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '2e512c37-ca60-4f83-864c-c7d7032f9cef',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱芯环保科技（厦门）股份有限公司' LIMIT 1),
  '《厦门市新型研发机构管理办法》的政策解读',
  0,
  '建议申报重点新型研发机构（而非重大机构），因为：1）科技人员占比和研发人员数量已满足重点机构要求；2）年度研发投入446.93万元超出重点机构200万元要求。但需重点解决以下问题：1）提升研发投入强度至30%以上，建议增加研发投入约200万元或提升营收规模；2）补充研发设备原值证明材料，确保不低于200万元；3）核实经营范围是否包含研发相关表述；4）明确核心技术方向与政策支持领域的关联性；5）建立新型研发机构治理架构和管理制度。鉴于研发投入强度差距较大，建议先进行内部整改后再申报。'
);
