INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'a77fc3b0-3d4c-429e-82dc-3931fdad2c11',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱芯环保科技（厦门）股份有限公司' LIMIT 1),
  '关于组织申报2026年厦门市应用场景类揭榜挂帅项目（生物技术与生物制造领域）的通知',
  1,
  '**暂不推荐申报该政策。** 主要障碍：1）该政策要求技术供给方与场景供给方联合申报，企业缺少场景供给方合作，属于一票否决项；2）企业核心技术领域为环保设备制造，与政策支持的生物技术与生物制造领域严重不匹配。建议：1）如确有生物技术相关业务，需提供证明材料并寻找场景供给方联合申报；2）可关注其他环保、绿色低碳相关政策，如厦门市绿色低碳、节能环保等领域专项政策；3）企业可先完善技术产品的检测认证，为后续申报做准备。'
);
