INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'b0dc8cd3-f5a0-4e8f-9cc1-e465836552ee',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱芯环保科技（厦门）股份有限公司' LIMIT 1),
  '2026年度重大科技成果购买补助项目申报指南',
  1,
  '**暂不推荐申报该政策。** 虽然企业在研发投入、知识产权、高企资格等方面表现优秀，但注册地为厦门（计划单列市）是刚性一票否决条件，政策明确排除计划单列市企业。建议：1）优先寻找针对厦门市的专项政策；2）如确有技术交易需求，可关注福建省内其他不限制注册地的科技政策；3）该企业资质优秀，建议申报高新技术企业认定相关奖励、研发费用补助等厦门市级或国家级普惠性政策。'
);
