INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '0e209244-22a8-4b47-adc4-694ad8ed3a94',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱芯环保科技（厦门）股份有限公司' LIMIT 1),
  '2026年度国家重大科技项目和国家级科技创新平台奖补资金申报指南',
  1,
  '**暂不推荐申报该政策。** 该政策为定向奖补政策，申报主体须为2023年度已获我省奖补的国家重大科技项目或2025年7月7日至申报截止日新获批的国家级科技创新平台。企业虽具备独立法人资格、注册地符合要求、信用良好、高新技术企业资质等基础条件，但未获得国家重大科技项目立项或国家级科技创新平台认定，不具备申报主体资格。建议企业：（1）积极争取国家重大科技项目立项；（2）努力申报国家级科技创新平台（如国家技术创新中心、全国重点实验室等）；（3）关注其他适合企业当前资质的科技政策。'
);
