INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'cda5a21a-984c-45d1-a6a0-faea774853a1',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱芯环保科技（厦门）股份有限公司' LIMIT 1),
  '2026年度支持设区市农科院所建设专项项目申报指南',
  1,
  '该企业**不建议申报**此政策。虽然企业在研发投入、知识产权、科技人员等方面表现优秀，但存在两个一票否决的前置条件：(1)企业在厦门注册，政策明确排除厦门地区；(2)政策要求申报主体为公益类农业科研院所，而企业是商业性质的制造业公司。此外，企业所属行业为专用设备制造业，与政策支持的农业领域完全不符。建议企业寻找与环保科技、专用设备制造相关的政策进行申报。'
);
