INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'c15bf280-7331-49aa-9cb2-265c7d8996f2',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱芯环保科技（厦门）股份有限公司' LIMIT 1),
  '厦门市科学技术局关于组织申报2026年度国家科技重大项目资金配套的通知',
  0,
  '**暂不推荐申报该政策。** 该政策是资金配套政策，核心申报条件是企业必须承担国家科技重大项目并获得立项，同时2025年度要有到位国家资助资金。但企业信息中完全没有提到是否承担国家科技重大项目、是否获得立项、是否有国家资助资金到位等关键信息，这是申报的【一票否决项】。建议：1. 首先确认企业是否承担了国家科技重大项目（如国家重点研发计划、国家科技重大专项等）；2. 如已承担，确认是否已获得立项批复；3. 确认是否有2025年度到位的国家资助资金；4. 如具备上述条件，可准备相关证明材料进行申报；5. 如不具备上述条件，建议关注其他适合企业现状的科技政策。'
);
