INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '801ef634-2602-4e72-a812-480a902d19eb',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门斯坦道科学仪器股份有限公司' LIMIT 1),
  '2026年度引导性项目申报指南',
  0,
  '强烈推荐申报。该企业完全满足政策的前置条件要求，注册地在厦门且具有独立法人资格，无失信记录。仪器仪表制造业可广泛应用于工业科技、农业科技、社会发展科技领域，与政策支持方向高度契合。企业研发实力雄厚（研发费用785.43万元，加计扣除480.63万元），拥有丰富知识产权（113件），总得分92分，具备较强的项目申报竞争力。建议重点围绕仪器仪表在工业检测、农业科技、环境监测等领域的创新应用设计项目，突出技术创新性和应用价值，同时确保项目属于应用开发类而非基础研究类，并提前建立研发准备金制度。'
);
