INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '4fce41dc-0513-4e25-8e43-c367a5692459',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门斯坦道科学仪器股份有限公司' LIMIT 1),
  '2026年厦门市支持联合实验室建设工作指引',
  0,
  '该企业整体资质优秀，前置条件全部满足，核心条件表现突出，强烈推荐申报2026年厦门市支持联合实验室建设。建议申报前重点做好以下准备工作：1）与共建单位签订期限不少于3年的正式共建协议；2）梳理近三年横向科研经费到账情况，确保每年到账额不少于100万元；3）提供科研用房面积证明，确保不少于1000平方米；4）整理近三年前期合作基础证明材料（科研项目、产学研合作、知识产权、标准制定等）。企业知识产权储备丰富（113件）、研发投入强度高（13.01%）、科技人员配置充足（20人），为联合实验室建设提供了坚实基础。'
);
