INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'b667743c-c73e-4b38-9aa3-898e3ed72fc5',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门斯坦道科学仪器股份有限公司' LIMIT 1),
  '关于组织申报2024年公共技术服务平台项目的通知',
  0,
  '建议暂缓申报或深入论证。该政策主要面向公共技术服务平台建设，要求申报主体具备龙头骨干企业资格或高校科研院所身份，且平台需具备基础性、开放性、公益性特征，技术服务收入占比需达60%以上。该企业为仪器仪表制造企业，性质上偏向生产制造而非技术服务，与政策要求的平台属性存在较大差距。建议企业：一、确认是否被认定为龙头骨干企业；二、论证平台是否具备公共服务属性；三、如确需申报，需补充服务场所面积、设备投资等证明材料，并调整平台定位，突出其在科学仪器检测、校准等方面的公共服务功能。'
);
