INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '6e7fc951-094e-43d3-ae76-22fb0eded537',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门斯坦道科学仪器股份有限公司' LIMIT 1),
  '2026年度国家重大科技项目和国家级科技创新平台奖补资金申报指南',
  1,
  '**暂不推荐申报该政策。** 该政策为专项奖补政策，申报前提条件为：须为2023年度已获我省奖补的国家重大科技项目，或2025年7月7日至申报截止日新获批的国家级科技创新平台（全国重点实验室、国家技术创新中心等）。企业虽具备良好的科技创新基础（高新技术企业、研发投入高、知识产权丰富），但不具备政策要求的国家重大科技项目或国家级科技创新平台资质，一票否决，无法申报。建议企业关注其他适合仪器仪表制造业的科技奖补政策，如研发费用加计扣除、技术改造奖补等普惠性政策。'
);
