INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '14a6ac28-2eea-447e-91c8-f38307c6e09a',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门斯坦道科学仪器股份有限公司' LIMIT 1),
  '同安区2025年国家高新技术企业认定奖励申报',
  1,
  '**暂不推荐申报该政策。** 企业注册地和实际经营地址均在思明区/火炬高新区，不在同安区，不满足该政策的核心前置条件（注册地区要求）。虽然企业具备高企资质、研发投入高、知识产权丰富等优势，但注册地不符合是硬性一票否决项。建议：1）优先寻找思明区或火炬高新区的高企认定奖励政策；2）如需申报同安区政策，需将企业注册地变更至同安区（但变更流程复杂且需满足相关条件）。'
);
