INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '8ac4176a-a534-4e30-867c-fb2e6e4fb217',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门斯坦道科学仪器股份有限公司' LIMIT 1),
  '厦门市科学技术局关于组织申报2026年度国家科技重大项目资金配套的通知',
  0,
  '该企业基础资质优秀（高新技术企业、研发机构完善、信用良好、知识产权丰富），但该政策为资金配套政策，核心申报条件是须承担国家科技重大项目并获得立项及实际到位资金。企业信息中未提及相关国家科技项目情况，这是申报的最大障碍。建议：1.核实企业是否承担国家重点研发计划、国家科技重大专项等项目；2.若有相关项目，确认立项时间和到位资金情况；3.若无相关项目，建议申报其他科技政策（如高新技术企业认定奖励、研发费用补贴等）；4.该企业适合申报研发费用加计扣除、科技型中小企业认定等普惠性政策。'
);
