INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '92b17175-e8f3-471e-a90b-f83591b6f47a',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门彼格科技有限公司' LIMIT 1),
  '2025年度厦门市科学技术奖提名工作的通知',
  0,
  '企业整体资质优秀，完全满足科学技术奖的基本申报条件。建议立即开展以下工作：1）梳理企业已完成的科技成果，确认是否已办理科技成果登记，如有遗漏尽快补办；2）确认拟申报项目的技术应用时间是否在2024年5月31日前；3）整理55件知识产权与拟申报成果的关联性证明材料；4）准备完整的项目验收报告、技术鉴定报告等支撑材料；5）由于企业未获得科技奖励，需重点突出技术创新性和先进性。建议优先选择核心技术先进、知识产权关联度高、已产生显著经济社会效益的成果进行申报。'
);
