INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'fe59d637-eb8a-4e3a-b6e9-fbcc881c8675',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门彼格科技有限公司' LIMIT 1),
  '2025年福建省院省科技合作计划项目管理实施细则',
  0,
  '该企业整体资质优秀，但申报福建省院省科技合作计划项目的关键前提是与中国科学院院属研究所建立联合申报关系。建议：1.优先寻找与计算机、通信、电子信息等领域相关的中科院院属研究所进行对接；2.明确合作技术方向，准备技术合同；3.确认合作经费比例安排（30%或50%以上）；4.充分利用企业现有的研发实力和知识产权优势，提升项目竞争力。完成院省合作对接后，可达到A级申报标准。'
);
