INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '881008aa-01b0-4847-88c9-66bf594f80bf',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门彼格科技有限公司' LIMIT 1),
  '2025年 厦门市新型研发机构管理办法',
  0,
  '该企业研发投入金额和人员规模表现优秀，但存在两个关键风险点：一是企业性质为制造业，与政策\'不包括主要从事生产制造\'的要求存在冲突；二是研发投入强度（12.42%）远低于30%要求。建议：（1）首先确认企业主营业务中研发技术服务收入占比是否超过50%，以证明不属于\'主要从事生产制造\'；（2）如能提供充分证据证明以研发为主业，可尝试申报重点新型研发机构（门槛相对较低）；（3）重点补充研发设备原值证明、研发管理制度文件等材料；（4）建议先咨询主管部门确认企业性质是否符合申报资格，再决定是否申报。'
);
