INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'ffc50a8f-e33c-47d5-b66c-96f84deeb53b',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门彼格科技有限公司' LIMIT 1),
  '厦门市留学人员创业扶持工作指引',
  1,
  '**暂不推荐申报该政策**。企业存在两个一票否决的前置条件：1）成立年限已满11年，远超政策规定的5年以下限制；2）无法确认是否为留学人员创办企业。该政策专门面向留学人员创业扶持，企业不符合申报主体要求。建议：1）寻找其他不限制成立年限和创办主体的科技政策；2）如确实为留学人员创办，需补充相关证明材料；3）考虑申报厦门市其他科技型企业扶持政策。'
);
