INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '85016be9-f4b5-42c1-bcc1-40b0dc37b76a',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门彼格科技有限公司' LIMIT 1),
  '海沧区2025年国家级高新技术企业认定奖励',
  1,
  '该企业各项指标优秀，但因注册地在同安区而非海沧区，不符合本政策的注册地要求，属于一票否决项。建议：1）优先寻找同安区或火炬高新区的高新技术企业认定奖励政策；2）如符合条件可申报海沧区政策，建议关注后续年度政策调整或企业是否有意向迁址至海沧区；3）该企业如为2024年度首次认定高企，可获得首次认定20万元+营收叠加30万元=50万元奖励。'
);
