INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '72705b25-707f-4910-95aa-8a3aa9bb50b9',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门彼格科技有限公司' LIMIT 1),
  '《厦门市新型研发机构管理办法》的政策解读',
  0,
  '建议申报重点机构而非重大机构。当前企业研发投入强度（12.42%）远低于政策要求的30%，这是最大障碍。建议：1）优化财务核算结构，提高研发投入在收入中的占比至30%以上；2）完善研发管理制度，建立现代企业治理结构；3）补充研发设备原值专项审计报告；4）先申请市级新型研发机构认定，再申报重点机构。企业科技人员、研发投入金额、知识产权等基础条件优秀，信息技术领域完全契合政策方向，申报潜力较大。'
);
