INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '30ca5156-049a-45fe-afb5-dc85443d2c8a',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门彼格科技有限公司' LIMIT 1),
  '厦门市科学技术局关于组织申报2026年度国家科技重大项目资金配套的通知',
  1,
  '**暂不推荐申报本政策。** 核心原因：企业未承担国家科技重大项目并获得立项，这是申报本政策的\'一票否决\'条件。尽管企业在注册地、信用、研发投入、知识产权等方面表现优秀，但缺少国家科技重大项目立项这一核心前提，导致无法满足政策要求。建议企业：（1）积极争取参与国家科技重大项目，可通过与高校、科研院所联合申报的方式参与；（2）关注国家重点研发计划、科技重大专项等项目的申报通知，提前布局；（3）待获得国家科技重大项目立项并有资金到位后，再行申报此类资金配套政策。'
);
