INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '5818b3d7-daf2-4821-b794-6c253701786d',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门彼格科技有限公司' LIMIT 1),
  '2026年度科技特派员后补助项目申报指南',
  1,
  '**暂不推荐申报该政策。** 虽然企业在法人资格、注册地、信用状况、研发能力等方面表现优秀，但该政策为科技特派员后补助项目，核心要求是围绕农业特色产业或乡村振兴相关产业链开展技术开发。企业属于计算机、通信和其他电子设备制造业，行业领域与政策要求完全不匹配，属于一票否决项。建议企业关注其他与电子信息、光电产业相关的科技政策，或考虑向农业领域转型后再申报此类政策。'
);
