INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '691a6e3c-b614-4cc3-b58f-2bfdd7b4e9d2',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱德森（厦门）电子有限公司' LIMIT 1),
  '2026年度福建省院省科技合作计划项目申报指南',
  1,
  '【暂不推荐申报】该政策为院省科技合作项目，存在一票否决项：企业缺少与中科院院属研究所的联合申报关系，这是申报的前提条件。同时年度研发投入751.46万元远低于2000万元要求，差距较大。建议：(1)优先寻找合适的中科院院属研究所建立合作关系，获取联合申报支持；(2)若能解决联合申报问题，可同步提升研发投入至2000万元以上并建立研发准备金制度；(3)该企业更适合申报厦门市地方科技政策或其他不要求联合申报的省级科技计划项目。'
);
