INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '62bb17ea-d8cb-4a5d-907a-4045dd119943',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱德森（厦门）电子有限公司' LIMIT 1),
  '关于组织申报2025年度市级新型研发机构的通知',
  0,
  '建议申报【重点层级】新型研发机构。企业研发投入751.46万元远超重点层级200万要求，科技人员占比31.08%达标，但研发投入强度仅16.64%未达30%要求。建议：1）补充研发设备原值证明材料（需≥200万元）；2）完善研发管理制度和章程；3）进一步明确核心技术领域与政策的契合度；4）如条件允许，提升研发投入强度至30%以上，可增强申报竞争力。暂不推荐申报重大层级，因科技人员占比、设备原值、累计支出等多项指标存在差距。'
);
