INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '968a8e75-e8bc-48a9-8060-68282f8b167e',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱德森（厦门）电子有限公司' LIMIT 1),
  '厦门市留学人员创业扶持工作指引',
  1,
  '该企业虽然在研发投入、人员规模、技术领域等方面均完全符合甚至远超政策要求，但存在两个致命的前置条件缺陷：1）企业成立32年，远超政策规定的5年限制；2）无法确认留学人员创办身份。根据一票否决原则，该企业**不具备申报厦门市留学人员创业扶持的资格**。建议：1）该政策明确要求成立5年以内的企业，该企业已超期27年，无法补救；2）建议企业关注其他适合成熟期科技企业的扶持政策，如研发费用加计扣除、高新企业认定奖励等；3）如确实有留学人员创办背景，可考虑其他不限制成立年限的人才创业政策。'
);
