INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '67d24517-3408-49a2-92da-9114df4b0586',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱德森（厦门）电子有限公司' LIMIT 1),
  '《厦门市新型研发机构管理办法》的政策解读',
  0,
  '企业整体基础较好，但存在两个关键短板：一是研发投入强度（16.64%）远低于政策要求的30%，需将研发投入提升至1354万元以上才能达标；二是研发设备原值数据缺失。建议：（1）优先申报市级新型研发机构，积累认定经验；（2）通过增加研发项目、加大研发投入等方式提升研发投入强度至30%以上；（3）补充研发设备原值证明材料；（4）梳理企业技术方向与政策支持领域的关联性，突出在信息技术、智能制造等领域的创新成果。目前可尝试申报，但需重点解决研发投入强度问题。'
);
