INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'a8f7802c-62fc-4b33-a86b-715e45255d5e',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱德森（厦门）电子有限公司' LIMIT 1),
  '2025年福建省院省科技合作计划项目管理实施细则',
  1,
  '**暂不推荐申报该政策。** 主要障碍：1）注册地归属存在争议（厦门为计划单列市）；2）缺少与中国科学院院属研究所的合作关系，这是政策的一票否决项。建议：1）立即联系福建省科技厅确认厦门企业是否有申报资格；2）如确认有资格，需尽快与中国科学院相关研究所建立合作关系并签订技术合同；3）可考虑同时申报厦门市同类科技政策作为备选。'
);
