INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '5d80ddf8-dbc9-462a-ad59-498197cc8e11',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱德森（厦门）电子有限公司' LIMIT 1),
  '2026年度发展中国家技术培训班项目申报指南',
  0,
  '该企业虽然在科技资质、财务状况、研发能力等方面表现优秀，但与2026年度发展中国家技术培训班项目的匹配度较低。主要问题在于：1）企业主营业务为仪器仪表制造，与技术培训班项目实施无直接关联；2）企业核心技术领域与政策支持的人工智能、可持续发展、生命健康等方向不匹配；3）企业缺乏技术培训班实施经验和国际科技合作基础。

建议：暂不推荐申报该政策。如企业有意向开展国际技术培训合作，建议先积累相关经验或考虑与有培训资质的机构合作。未来可关注其他更符合企业主营业务方向的科技政策。'
);
