INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '1a550f5e-94e3-488e-a0f3-93b338ac044a',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '爱德森（厦门）电子有限公司' LIMIT 1),
  '2026年度省属公益类科研院所基本科研项目申报指南',
  1,
  '**强烈不建议申报该政策。** 该政策的核心申报主体要求为"省属公益类科研院所"，而爱德森（厦门）电子有限公司是企业性质的商业主体，属于制造业（仪器仪表制造业），与政策要求的科研院所性质完全不符。这是一票否决项，无论企业的高新资质、研发投入、知识产权等条件多么优秀，都无法申报该政策。建议企业寻找针对高新技术企业或制造业企业的专项政策进行申报。'
);
