INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'cbbf536c-3869-434c-bc9a-d6353cfc97d4',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门蔚扬药业有限公司' LIMIT 1),
  '国家高新技术企业认定',
  0,
  '强烈推荐申报。企业各项指标全面达标且大幅超过要求：科技人员占比62.5%（要求≥10%）、研发投入强度25.94%（要求≥5%）、拥有7件I类知识产权。已是高企身份，申报经验丰富。建议重点关注：1）确保研发费用辅助账规范归集；2）整理好知识产权与核心技术产品的关联性；3）完善科技成果转化证明材料。利润亏损不影响高企认定，但需在申报材料中合理解释原因（如加大研发投入）。'
);
