INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'b52e2d8e-fc62-4394-850e-967f265d4136',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门蔚扬药业有限公司' LIMIT 1),
  '国家重点研发计划管理暂行办法',
  0,
  '强烈推荐申报。企业完全满足国家重点研发计划的所有前置条件和核心要求，特别是在研发投入强度（25.94%）、科技人才占比（62.5%）和知识产权储备（7件I类专利）方面表现突出。医药领域高度契合\'面向人民生命健康\'政策方向，是国家重点支持的战略性领域。建议重点准备以下内容：1）突出企业在医药细分领域的技术领先优势；2）充分展示研发团队实力和高层次人才背景；3）论证项目对国家重大需求的支撑作用；4）制定合理的资金使用计划和成果转化方案。由于企业处于亏损状态，需在申报材料中重点说明项目资金保障措施和预期经济效益，增强评审信心。'
);
