INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '8d88a421-83a3-4d1b-a71e-719c44ec6477',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门蔚扬药业有限公司' LIMIT 1),
  '厦门市科学技术局关于开展2024年度高新技术成果转化项目认定的通知',
  0,
  '该企业整体资质优秀，建议积极申报。核心优势在于：1）发明专利数量充足（7件），远超政策要求；2）研发投入强度高（605万元，占销售收入25.94%）；3）科技人员占比高（62.5%）；4）属于国家重点支持的高新技术领域。主要风险点是软件著作权要求对药业企业可能不适用，建议：1）与主管部门确认软件著作权是否为必须条件；2）准备充分的知识产权证明材料；3）重点突出生物医药领域的技术成果转化项目；4）提供详细的研发项目立项和成果转化证明材料。综合评分90.83分，评级A级，强烈推荐申报。'
);
