INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '290631f5-58d1-456a-a19a-9c3d8e52fbd8',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门蔚扬药业有限公司' LIMIT 1),
  '2026年度福建省院省科技合作计划项目申报指南',
  0,
  '企业整体资质较好，研发投入强度、知识产权、行业领域等均符合政策要求，但存在两个关键障碍：一是年度研发投入605万元远低于2000万元优先推荐标准，差距较大；二是政策要求必须与中科院院属研究所联合申报，这是刚性要求。建议企业：1.尽快寻找合适的中科院院属研究所建立合作关系；2.建立研发准备金制度并完成备案；3.确认项目负责人及企业在研项目情况；4.由于研发投入差距较大，即使满足其他条件，评审排序也可能靠后，可考虑同时申报其他更匹配的政策。'
);
