INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '153a962a-d1ff-40b6-b0c8-6c7235be0735',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门蔚扬药业有限公司' LIMIT 1),
  '福建省科技计划项目管理办法',
  0,
  '企业基本符合福建省科技计划项目管理办法的申报条件，建议积极申报。前置条件全部满足，研发投入强度远超政策要求（25.94% vs 5%），是重要加分项。建议重点关注：1）明确建立研发准备金制度以满足门槛条件；2）如需申报省级新型研发机构相关后补助项目，需先申请省级新型研发机构认定；3）准备完善的研发项目材料，突出技术先进性和行业带动作用。鉴于企业为高新技术企业且研发投入强度突出，可获得较高评审分数。'
);
