INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '7cf0f0d2-8660-4731-9448-6cedc29a2878',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门蔚扬药业有限公司' LIMIT 1),
  '厦门市新型研发机构管理办法',
  0,
  '企业整体符合新型研发机构的基本申报条件，建议申报重点新型研发机构（因研发设备原值和收入结构存在不确定性，暂不推荐直接申报重大级）。申报前需重点完善以下事项：1）补充研发设备原值证明材料，确保不低于200万元；2）明确技术开发等服务收入金额及占比，确保不低于100万元且占主营业务收入40%以上；3）建立完善的研发管理制度（理事会决策制、章程管理等）；4）适当提升研发投入强度至30%以上。鉴于企业已具备高新技术企业资格、充足的研发投入和高比例研发人员，申报成功概率较高。'
);
