INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'f322a4f5-ccc2-4d2c-b7d8-a5f54876be61',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门蔚扬药业有限公司' LIMIT 1),
  '2026年度省创新战略研究项目申报指南',
  1,
  '**暂不推荐申报该政策。** 该政策主要面向高等院校、省属事业单位等科研机构，企业仅在设立智库且纳入福建省重点智库名单的情况下可申报。厦门蔚扬药业有限公司为一般性商业企业，不属于政策允许的申报主体范围，这是申报的一票否决项。建议企业：一是关注是否具备条件设立企业智库并申请纳入福建省重点智库名单；二是转向其他适合企业申报的科技政策，如高新技术企业认定后补助、技术改造项目等；三是该企业可考虑申报省级科技计划项目中明确面向企业的专项政策。'
);
