INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '2a15916c-5c79-4da1-be5c-3209a9d688bd',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门蔚扬药业有限公司' LIMIT 1),
  '2026年度创新药物研发奖励资金补助项目',
  1,
  '【不推荐申报】该政策明确要求申报单位在福建省注册（不含厦门市），而厦门蔚扬药业有限公司注册地址为厦门市海沧区，属于政策明确排除的范围，构成一票否决项。即使企业具备良好的研发能力（研发费用605万元、科技人员20人、高新技术企业资质），也无法申报该政策。建议企业关注福建省内其他生物医药相关政策，或等待该政策范围调整后重新评估。'
);
