INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '418cff1b-66a4-453a-a44a-df956cd09be7',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门海迈科技股份有限公司' LIMIT 1),
  '厦门市高新技术成果转化项目认定操作规程（试行）',
  0,
  '企业整体资质优秀，完全满足政策的基本申报条件，建议积极申报。建议重点做好以下准备：1）梳理近3年内授权的发明专利和近2年内授权的实用新型、软件著作权，确保知识产权时间符合要求；2）明确具体的高新技术成果转化项目，准备项目技术先进性、转化效果等相关证明材料；3）准备产品检测认证报告；4）准备高新技术成果转化的经济效益、社会效益说明材料；5）由于企业利润为负，需重点说明项目转化后的预期收益和盈利前景。可申报金额按销售收入分段计算，最高可达100万元。'
);
