INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'fadbc5da-660a-40f5-9c6a-c8b2f885bf2e',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门海迈科技股份有限公司' LIMIT 1),
  '2026年度重大科技成果购买补助项目申报指南',
  1,
  '**暂不推荐申报该政策。** 该政策明确要求申报企业为福建省内企业（计划单列市除外），而厦门市属于计划单列市，企业注册地在厦门，不符合政策的前置条件要求，属于一票否决项。尽管企业在研发投入、高企资格、产业领域等方面均符合甚至远超政策要求，但注册地限制导致无法申报。建议：1）关注福建省针对厦门市的其他专项政策；2）如政策范围调整或厦门市被纳入支持范围，该企业具备较强的申报优势；3）可考虑申报其他不限制注册地的同类政策。'
);
