INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'af4a870f-d0e1-4eca-8119-3b3dc15423d0',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门海迈科技股份有限公司' LIMIT 1),
  '2025年 厦门市新型研发机构管理办法',
  0,
  '该企业整体资质较好，研发投入、人员和强度均远超政策要求，信息技术领域完全契合政策支持方向。建议优先采取以下行动：1）补充研发设备原值证明材料；2）确认是否已获市级新型研发机构认定，如未获批需先申报市级；3）完善公司章程，建立符合要求的治理架构；4）提供科研场所独立性证明；5）明确累计建设运营支出金额。完成上述补充后，可申报重点新型研发机构，条件成熟后再申报重大层级。'
);
