INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'a7bda8ed-2e3e-4b94-a08c-3a2f0d533bd3',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门海迈科技股份有限公司' LIMIT 1),
  '2026年度发展中国家技术培训班项目申报指南',
  0,
  '该政策为国家级科技援外培训项目，对申报主体的主营业务和项目实施经验有明确要求。厦门海迈科技股份有限公司虽具备高新技术企业资质和较强的研发能力，但主营业务为软件和信息技术服务，与技术培训班项目实施无直接关联，且缺乏国际培训办班经验。建议暂不申报此类援外培训项目，可关注其他更匹配企业主业的科技政策（如高新技术企业认定复审、研发费用加计扣除、科技项目资助等）。如确有申报意愿，需先积累国际培训项目经验或与有办班资质的企业/机构合作。'
);
