INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'ee79f595-8148-4c0c-9aed-bb6463130e05',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门海迈科技股份有限公司' LIMIT 1),
  '2026年度国家重大科技项目和国家级科技创新平台奖补资金申报指南',
  1,
  '**暂不推荐申报该政策。** 虽然企业在注册地、独立法人资格、信用状况、研发投入等方面均符合要求，但该政策的核心申报条件是须为已获批的国家重大科技项目或国家级科技创新平台。企业信息中未显示获得此类项目或平台认定，因此不满足申报主体资格要求。建议企业：1）优先申报其他科技资质类、研发费用类政策；2）如有意向申报此类政策，应积极争取参与国家重大科技项目或申报国家级科技创新平台；3）可关注厦门市地方性科技奖补政策，可能更适合企业当前发展阶段。'
);
