INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '66d5f823-ec6d-47a2-8f1f-e28c711b04e2',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门海迈科技股份有限公司' LIMIT 1),
  '厦门市科学技术局关于组织申报2026年度国家科技重大项目资金配套的通知',
  1,
  '**暂不推荐申报该政策。** 该政策为资金配套政策，核心申报条件是须承担国家科技重大项目并获得立项，这是前置条件中的一票否决项。企业虽具备较强的研发实力（研发投入2177.93万元、知识产权29件、科技人员98人），但未满足"承担国家科技重大项目"这一核心前提条件。建议企业：(1)积极争取参与国家科技重大项目的申报和实施；(2)关注厦门市其他科技扶持政策，如研发费用补助、高新企业奖励等；(3)待获得国家科技重大项目立项后再申报此类资金配套政策。'
);
