INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  '4952a599-487d-4b8e-89fd-3c07f36475f4',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门承葛生物科技有限公司' LIMIT 1),
  '海沧区2025年国家级高新技术企业认定奖励',
  1,
  '企业各项指标优秀，但因注册地在翔安区而非海沧区，不符合该政策的注册地要求，属一票否决项，无法申报海沧区2025年国家级高新技术企业认定奖励。建议：1）关注厦门市科技局或翔安区发布的同类高企认定奖励政策；2）如企业有在海沧区设立子公司或迁址计划，可考虑以海沧区主体申报；3）当前可申报厦门市或其他区级同类政策。'
);
