INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'a10e3c82-012e-4bd1-a5d1-d8109a954e5a',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门承葛生物科技有限公司' LIMIT 1),
  '2025年 厦门市新型研发机构管理办法',
  0,
  '企业整体资质较好，建议申报重大新型研发机构认定。核心优势明显：研发投入1488.16万元（超要求197%）、研发人员21人（超要求5%）、研发人员占比41.18%（超要求1.18%）、核心技术领域为生物医药完全契合政策方向。主要风险点：一是研发设备原值未提供，需补充证明材料确保达到1000万元；二是累计投资情况需确认是否满足2000万元要求；三是研发投入强度29.27%略低于30%，建议适当提升；四是需确认是否已认定为市级新型研发机构。建议优先补充研发设备原值证明和累计投资证明材料，若设备原值不足1000万元可考虑申报重点新型研发机构（要求200万元）。'
);
