INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'b2ba0536-6c55-4eb5-8416-510374b80227',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门承葛生物科技有限公司' LIMIT 1),
  '2026年度重大科技成果购买补助项目申报指南',
  1,
  '**暂不推荐申报该政策。** 核心原因：企业注册地为厦门，属于计划单列市，而政策明确要求福建省内企业（计划单列市除外），这是一票否决的前置条件。尽管企业在研发投入、知识产权、高企资格等方面表现优秀，但注册地不符合是根本性障碍，无法通过其他条件弥补。建议：1.关注福建省内非计划单列市（如福州、泉州、漳州等地）的同类政策；2.如确有技术交易需求，可考虑在福建省内其他城市设立子公司作为申报主体；3.该企业可关注厦门市本地的科技成果转化相关政策。'
);
