INSERT INTO `match_result` (`uid`, `enterprise_uid`, `政策标题`, `一票否决`, `总体建议`) VALUES (
  'b2dab6a2-bc2e-4d6b-bb85-f828f1e19bf3',
  (SELECT `uid` FROM `enterprise` WHERE `企业名称` = '厦门承葛生物科技有限公司' LIMIT 1),
  '关于发布2026年度发展中国家技术培训班项目申报指南的通知',
  1,
  '【不推荐申报】该政策为发展中国家技术培训班项目，要求申报单位具备技术培训班组织与实施能力。厦门承葛生物科技有限公司主营业务为微生态医疗产品研发生产，与技术培训班组织完全无关，属于前置条件不满足（一票否决）。即使企业在生命健康技术领域有一定积累，但缺乏国际培训经验、外籍学员渠道和国际科技合作基地资质，申报成功可能性极低。建议企业关注与自身主营业务相关的科技政策，如生物医药研发支持、高新技术企业产业化等政策。'
);
